        .into());
    }

    if (r.end - r.start) > usize::MAX as u64 {
        return Err(PyValueError::new_err(format!(
            "Range {} is larger than system memory limit {}",
            r.start,
            usize::MAX
        ))
        .into());
    }

    Ok(r)
}

