pub(crate) struct PyPutMode(PutMode);

impl<'py> FromPyObject<'py> for PyPutMode {
    fn extract_bound(ob: &Bound<'py, PyAny>) -> PyResult<Self> {
        if let Ok(s) = ob.extract::<PyBackedStr>() {
